+        return forbidFeedbackRecord(requestId, instance);
+      }
+      log.warn(
+        { hubStatus: result.error?.status, hubCode: result.error?.code },
+        "Hub updateFeedbackRecord failed"
+      );
+      return hubErrorToProblemResponse(result.error, requestId, instance);
+    }
